import {manaFloorLabel} from './expedition-mana-floor.mjs';
import {SPARRING_RULE,SPARRING_RIVALS,sparringSetup,sparringFrame} from './expedition-sparring.mjs';
import {SKILLS,GEAR,POS,ATTR,DEFENSES,trainingOptions} from './expedition-data.mjs';
import {ADVANCEMENTS} from './expedition-advancement-data.mjs';
import {commandCostText} from './expedition-media.mjs';
import {positionOnlyLabel} from './expedition-position-only.mjs';
import {stockFloorLabel} from './expedition-stock-floor.mjs';
import {scheduleLabel} from './expedition-schedule.mjs';
import {targetCountLabel} from './expedition-target-count.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modes={once:'本场一次',round:'每回合一次',repeat:'持续',cycle:'轮转'},types={melee:'近战',ranged:'远程',magic:'法术',mental:'心理'},outcomes={victory:'胜出',defeat:'落败',timeout:'24回合未分胜负'};
const target=t=>POS[t]||{self:'自身',all:'全体',healer:'治疗者',summoner:'召唤者',priority:'个人攻击阵位优先',supportPriority:'个人辅助阵位优先'}[t]||t;
const stock=s=>`药草 ${s.herb} / 符纸 ${s.rune} / 箭矢 ${s.arrow}`;
const equipment=g=>Object.values(g).map(id=>GEAR[id]?.name||id).join('、');
function planView(plan,unit){return ['prep','main'].map(phase=>`<h4>${phase==='prep'?'默认预备':'默认普通'}</h4><ol>${plan[phase].map(r=>`<li>${esc(SKILLS[r.skill].name)} → ${esc(target(r.target))} · ${modes[r.mode]}${esc(stockFloorLabel(r)+manaFloorLabel(r)+positionOnlyLabel(r)+scheduleLabel(r)+targetCountLabel(r))}<small>${esc(commandCostText(unit,r))}</small></li>`).join('')}</ol>`).join('')+`<p>条件救护：${plan.healing.enabled?'≤'+Math.round(plan.healing.threshold*100)+'%生命，'+esc(target(plan.healing.target))+'；沿当前救护优先/群援设置':'关闭'}。实际选取仍受存活、覆盖、装备与资源限制；无队友可覆盖时按原规则查后备。</p>`;}
function eventFacts(e){const d=e.detail,parts=[];if(d.reason)parts.push(d.reason+'；'+(d.consumedAction?'占用此次行动':'本次检查未占用行动'));if(Number.isFinite(d.mpBefore)&&Number.isFinite(d.mpAfter))parts.push('施放法力 '+d.mpBefore+' → '+d.mpAfter);if(d.item)parts.push('实际材料支付：'+({herb:'药草',rune:'符纸',arrow:'箭矢'}[d.item]||d.item)+' ×'+(d.itemAmount||1));if(Number.isFinite(d.attack))parts.push('攻击检定 '+d.attack+' / 防御检定 '+d.defense+'（'+(d.defenseProfile?.name||'自然防御')+'）');if(Number.isFinite(d.actual)){const recovery=['heal','item'].includes(e.type),resource=e.type==='item'&&d.resource==='mp'?'法力':'生命';parts.push((e.type==='mana-transfer'?'实际转入法力':recovery?'实际恢复':'实际伤害')+' '+d.actual+(recovery?' '+resource:'')+(Number.isFinite(d.hpBefore)?'；生命 '+d.hpBefore+' → '+d.hpAfter:Number.isFinite(d.before)?'；'+resource+' '+d.before+' → '+d.after:''));}if(d.formula)parts.push(d.formula);return parts.map(v=>`<p>${esc(v)}</p>`).join('');}
function playback(value,index,stale){const e=sparringFrame(value,index),s=value.summary;return `<div class="sparring-result"><h3>${esc(value.heroName)} vs ${esc(value.opponent.name)} · ${outcomes[s.outcome]}</h3><p class="sparring-validity" role="status">${stale?'配置或资产已变化；下方是旧演武快照，请重新演武核对当前配置。':'这份演武对应当前配置。'}结果仅保留在当前页面内存，刷新后清除。</p><p>种子 ${value.seed} · ${s.rounds} 回合 · 本人最终生命 ${s.heroHp} / 法力 ${s.heroMp} · 对手最终生命 ${s.opponentHp}。本人实际伤害 ${s.damage}，不含召唤物独立伤害；空过 ${s.failed}。${s.noRoleChecks?`追击职责无存活候选检查 ${s.noRoleChecks} 次，后备仍可能成功。`:''}</p><p>本次结束临时携行量：${stock(s.supplies)}。收益：0；未正式出征。</p><p>以下是逐事件后的实际快照；胜负已结算，回看不会重新随机或支付。</p><label>演武回放 · ${index+1} / ${value.report.events.length}<input type="range" id="sparring-timeline" min="0" max="${value.report.events.length-1}" value="${index}"></label><div class="bar"><button data-sparring-step="first" ${index===0?'disabled':''}>开场</button><button data-sparring-step="prev" ${index===0?'disabled':''}>上一事件</button><button data-sparring-step="next" ${index===value.report.events.length-1?'disabled':''}>下一事件</button><button data-sparring-step="last" ${index===value.report.events.length-1?'disabled':''}>结局</button><button data-sparring-export="true">导出演武快照</button></div><article class="sparring-event" aria-live="polite"><p>第 ${e.round} 回合 · ${esc(e.phase)} · 事件 ${e.id}</p><h4>${esc(e.text)}</h4>${eventFacts(e)}<p>此刻临时携行量：${stock(e.supplies)}</p></article><div class="sparring-units">${e.units.map(u=>`<article data-sparring-unit="${esc(u.id)}"><h4>${esc(u.name)}${u.owner?' · 召唤物':''}</h4><p>${u.side==='party'?'我方':'陪练'} · ${POS[u.pos]} · ${u.hp>0?'存活':'倒下'}<br>生命 ${u.hp} / ${u.maxHp} · 法力 ${u.mp} / ${u.maxMp}</p><p>当前效果：${esc(u.effects.map(f=>f.name+(f.active?'':'（待生效）')).join('、')||'无')}</p></article>`).join('')}</div><details><summary>此事件完整证据</summary><pre>${esc(JSON.stringify(e,null,2))}</pre></details></div>`;}
export function personalSparringView(g,tactics,{rivalId='shield',value=null,index=0,stale=false,open=false}={}){
 if(!g.command)return '';
 let setup,error;try{setup=sparringSetup(g,tactics,rivalId);}catch(e){error=e.message;}
 const rival=SPARRING_RIVALS[rivalId],u=rival.unit,member=g.members.find(m=>m.id===g.command.heroId);
 return `<section class="guild-panel personal-sparring" data-guild-pane="hero" id="personal-sparring"><details ${open?'open':''}><summary>个人演武 · 用自己的英雄练习</summary><p>${SPARRING_RULE}</p><p>对手是项目原创的固定陪练；全部数值与指令公开，不是原版在线决斗或现行服务器规则。陪练沿现有敌方每类60份独立临时材料；双方都按原技能/防御费用支付。</p><label>公开陪练 <select id="sparring-rival">${Object.entries(SPARRING_RIVALS).map(([id,r])=>`<option value="${id}" ${id===rivalId?'selected':''}>${r.name}</option>`).join('')}</select></label><p>${esc(rival.description)}</p><details class="sparring-dossier"><summary>${rival.name} · 公开配置</summary><p>前排 · 生命 ${u.hp} / 法力 ${u.mp} · ${esc(equipment(u.gear))}</p><p>${Object.entries(u.attrs).map(([k,v])=>ATTR[k]+' '+v).join(' / ')}（装备修正另按现有规则叠加）</p><p>技能基础：${Object.entries(u.skills).map(([k,v])=>SKILLS[k].name+' '+v).join('、')}；防御：${Object.entries(u.defenses).map(([k,v])=>types[k]+' '+DEFENSES[v].name).join('、')}。</p>${planView(u,u)}</details>${error?`<p class="ready-diff">当前配置无法演武：${esc(error)}</p>`:`<p class="sparring-own">自己的英雄：${esc(setup.heroName)} · ${esc(setup.heroRole)} · ${esc(equipment(setup.hero.gear))} · 初始生命 ${setup.hero.hp} / 法力 ${setup.hero.mp} · 种子 ${setup.seed}。读取公会实际资产，不采用准备草稿中的实验装备/训练。</p><details class="sparring-plan"><summary>本次默认指令与培养快照</summary>${planView(setup.hero,setup.hero)}<p>实际培养：${esc(Object.entries(setup.hero.training).map(([k,v])=>(trainingOptions(setup.heroId)[k]?.name||k)+' +'+v).join('、')||'无')}。已学课程：${esc(member.unlocked.map(k=>SKILLS[k].name).join('、')||'无')}；独立进阶：${member.advancement?esc(ADVANCEMENTS[member.advancement.path].name):'未选择'}。默认站位${POS[setup.hero.pos]}，专修${esc(SKILLS[setup.hero.trained]?.name||setup.hero.trained)}。逐房覆盖不用于演武，返回远征仍保留。</p></details>`}<div class="bar"><button class="primary" data-sparring-run="true" ${error||g.pending?'disabled':''}>按当前配置演武</button><button data-personal="tactics">调整我的默认战术 →</button><button data-personal="growth">我的成长 →</button></div>${g.pending?'<p class="ready-diff">请先领取正式远征结算，再进行个人演武。</p>':''}${value?playback(value,index,stale):'<p>尚未演武。运行后可逐事件检查本人、陪练及召唤物的实际行动。</p>'}</details></section>`;
}
